// Historical compatibility evidence must come from the shipped Worker, not a
// legacy-shaped project generated by today's validator. Invoked by Node gates.
import { access, mkdir, readFile, writeFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { resolve } from 'node:path';

const revision = '80630c7d280c71314702af791dbc0828d9ff8b0a';
const directory = resolve('.generated/base-worker');
async function run(command, args, cwd = process.cwd()) {
  const child = spawn(command, args, { cwd, stdio: 'inherit' });
  await new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('exit', code => code === 0 ? resolve() : reject(new Error(`${command} failed (${code}) while preparing historical Worker ${revision}.`)));
  });
}

export async function prepareBaseWorker() {
  try {
    if ((await readFile(`${directory}/.fixture-commit`, 'utf8')).trim() === revision) {
      await access(`${directory}/.generated/cms-seed.mjs`);
      return;
    }
  } catch { /* First preparation; no runtime fixture may be silently skipped. */ }
  // CI fetches history. A shallow local checkout must fetch this pinned commit.
  await run('git', ['cat-file', '-e', `${revision}^{commit}`]);
  await mkdir(directory, { recursive: true });
  const archive = spawn('git', ['archive', revision], { stdio: ['ignore', 'pipe', 'inherit'] });
  const extract = spawn('tar', ['-x', '-C', directory], { stdio: ['pipe', 'inherit', 'inherit'] });
  archive.stdout.pipe(extract.stdin);
  await Promise.all([archive, extract].map(child => new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('exit', code => code === 0 ? resolve() : reject(new Error(`Historical source extraction failed (${code}).`)));
  })));
  await run('npm', ['ci'], directory);
  await run('npm', ['run', 'build'], directory);
  await writeFile(`${directory}/.fixture-commit`, revision + '\n');
}
